// 生前真实提名与本人答复共用原权源预览；没有任何隐式Office、军令或财产交割。
#include "political_succession_nomination_detail.hpp"
namespace hanmo::resident {namespace {
// typed命令逐字段比较，不把同一报价换成另一候选或任职epoch。
bool same(const PoliticalSuccessionNominationCommand& a,const PoliticalSuccessionNominationCommand& b){if(a.index()!=b.index())return false;return std::visit([&](const auto& lhs){using T=std::decay_t<decltype(lhs)>;const auto& rhs=std::get<T>(b);if constexpr(std::is_same_v<T,PoliticalAnswerSuccession>)return lhs.nomination_fact_id==rhs.nomination_fact_id&&lhs.accept==rhs.accept;else{const auto& x=lhs.authority;const auto& y=rhs.authority;if(std::tie(x.organization_id,x.office_id,x.actor_id,x.authority_epoch)!=std::tie(y.organization_id,y.office_id,y.actor_id,y.authority_epoch))return false;if constexpr(std::is_same_v<T,PoliticalNominateSuccessor>)return std::tie(lhs.policy_id,lhs.candidate_actor_id,lhs.expected_office_epoch)==std::tie(rhs.policy_id,rhs.candidate_actor_id,rhs.expected_office_epoch);else return lhs.nomination_fact_id==rhs.nomination_fact_id;}},a);}
// 首职签发必须仍是原在任首领，作者副手代办不自动取得生前正式继位提名权。
Status issuer(const PoliticalSuccessionNominationContext& x,const PoliticalSuccessionPolicy& p,const ActingAuthority& a,const StableId& kind){auto source=read_political_succession_office(x.common,x.organizations,x.organization_catalog,p);if(!source.ok)return {false,{},source.error};if(source.value.vacant||source.value.holder_actor_id!=std::optional<StableId>{a.actor_id}||a.actor_id!=source.value.original_leader_actor_id||a.office_id!=p.leader_office_id||a.organization_id!=p.organization_id||a.authority_epoch!=source.value.office_epoch)return common_failure("PoliticalSuccessionOriginalLeaderRequired",p.id);auto membership=succession_detail::member_now(x,a.actor_id,p.organization_id);if(!membership.ok)return membership;auto original=check_authority(x.common,x.organizations,x.organization_catalog,a,kind,{ScopeRef::Kind::site,p.seat_place_id},0);if(!original.ok)return {false,{},original.error};return succession_detail::grant(x,p,p.nomination_grant_id,kind,x.common.tick());}
}
Outcome<PoliticalSuccessionNominationQuote> preview_political_succession_nomination(const PoliticalSuccessionNominationContext& x,const StableId& actor,const PoliticalSuccessionNominationCommand& command){
 auto fail=[](const Status& s){return Outcome<PoliticalSuccessionNominationQuote>{false,{},s.error};};
 if(actor!=x.common.state().metadata.player_actor_id)return fail(common_failure("PoliticalSuccessionPlayerRequired"));
 if(!x.player_before||!x.seat)return fail(common_failure("PoliticalSuccessionHistoricalReadersRequired"));
 auto valid=validate_political_succession_nominations(x);if(!valid.ok)return fail(valid);
 auto checked=std::visit([&](const auto& c)->Status{using T=std::decay_t<decltype(c)>;const PoliticalSuccessionNomination* old=nullptr;const PoliticalSuccessionPolicy* p=nullptr;
  if constexpr(std::is_same_v<T,PoliticalNominateSuccessor>){if(x.state.nominations.size()>=4096)return common_failure("PoliticalSuccessionHistoryCapacity");p=x.catalog.policies.find(c.policy_id);if(c.authority.actor_id!=actor||!p)return common_failure("PoliticalSuccessionPolicyUnknown");}
  else{if constexpr(std::is_same_v<T,PoliticalAnswerSuccession>){if(x.state.answers.size()>=8192)return common_failure("PoliticalSuccessionHistoryCapacity");}else if(x.state.withdrawals.size()>=4096)return common_failure("PoliticalSuccessionHistoryCapacity");old=x.state.nominations.find(c.nomination_fact_id);if(!old||(std::is_same_v<T,PoliticalAnswerSuccession>?old->candidate_actor_id:old->issuer_actor_id)!=actor)return common_failure("PoliticalSuccessionNotKnown");p=x.catalog.policies.find(old->policy_id);if(!p)return common_failure("PoliticalSuccessionPolicyUnknown");if(succession_detail::acceded(x,old->id))return common_failure("PoliticalSuccessionAlreadyAcceded",old->id);if(succession_detail::closed(x.state,old->id))return common_failure("PoliticalSuccessionAlreadyClosed",old->id);}
  auto v=succession_detail::contact(x,*p,actor);if(!v.ok)return v;v=x.seat(*p,x.common.tick(),{});if(!v.ok)return v;
  if constexpr(std::is_same_v<T,PoliticalNominateSuccessor>){
   if(c.candidate_actor_id==actor)return common_failure("PoliticalSuccessionDistinctCandidateRequired");v=issuer(x,*p,c.authority,political_succession_nominate_command);if(!v.ok)return v;if(c.expected_office_epoch!=c.authority.authority_epoch)return common_failure("PoliticalSuccessionOfficeVersionChanged");
   v=succession_detail::contact(x,*p,c.candidate_actor_id);if(!v.ok)return v;
   for(const auto& id:{actor,c.candidate_actor_id}){v=growth_independent_office_age(x.common,id);if(!v.ok)return v;v=succession_detail::member_now(x,id,p->organization_id);if(!v.ok)return v;}
   if(x.common.tick()>std::numeric_limits<Integer>::max()-p->response_ticks)return common_failure("PoliticalSuccessionDeadlineOverflow");
   for(const auto& row:x.state.nominations.rows())if(row.second.policy_id==p->id&&!succession_detail::closed(x.state,row.first)&&(succession_detail::accepted(x.state,row.first)||x.common.tick()<row.second.response_until))return common_failure("PoliticalSuccessionNominationAlreadyPending");
  }else if constexpr(std::is_same_v<T,PoliticalAnswerSuccession>){
   const auto* prior=succession_detail::accepted(x.state,old->id);if(c.accept&&prior)return common_failure("PoliticalSuccessionAlreadyAccepted");if(!prior&&x.common.tick()>=old->response_until)return common_failure("PoliticalSuccessionNominationExpired");
   if(c.accept){v=succession_detail::contact(x,*p,old->issuer_actor_id);if(!v.ok)return v;auto office=read_political_succession_office(x.common,x.organizations,x.organization_catalog,*p);if(!office.ok)return {false,{},office.error};if(office.value.holder_actor_id!=std::optional<StableId>{old->issuer_actor_id}||office.value.office_epoch!=old->office_epoch)return common_failure("PoliticalSuccessionNominationAuthorityChanged");v=growth_independent_office_age(x.common,actor);if(!v.ok)return v;v=succession_detail::member_now(x,actor,p->organization_id);if(!v.ok)return v;}
  }else{if(c.authority.actor_id!=actor||c.authority.authority_epoch!=old->office_epoch)return common_failure("PoliticalSuccessionOriginalLeaderRequired");v=issuer(x,*p,c.authority,political_succession_withdraw_command);if(!v.ok)return v;}
  return common_success();
 },command);return checked.ok?Outcome<PoliticalSuccessionNominationQuote>{true,{x.common.state().identity,actor,command},{}}:fail(checked);
}
// 原候选负责回滚；该writer只追加明确意愿，不产生正式就任或默认代理授权。
Outcome<StableId> apply_political_succession_nomination_in_candidate(CommonStore& common,PoliticalSuccessionNominationState& state,const PoliticalSuccessionNominationContext& x,const StableId& actor,const PoliticalSuccessionNominationCommand& command,const PoliticalSuccessionNominationQuote& quote){
 const auto& a=common.state().identity;const auto& b=quote.identity;if(&common!=&x.common||&state!=&x.state||quote.actor_id!=actor||!same(command,quote.command)||std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)!=std::tie(b.world_id,b.execution_epoch,b.revision,b.tick))return {false,{},common_failure("StalePoliticalSuccessionQuote").error};auto valid=preview_political_succession_nomination(x,actor,command);if(!valid.ok)return {false,{},valid.error};
 return std::visit([&](const auto& c)->Outcome<StableId>{using T=std::decay_t<decltype(c)>;StableId prefix,kind;if constexpr(std::is_same_v<T,PoliticalNominateSuccessor>){prefix="political_succession_nomination";kind="political_successor_nominated";}else if constexpr(std::is_same_v<T,PoliticalAnswerSuccession>){prefix=c.accept?"political_succession_acceptance":"political_succession_decline";kind=c.accept?"political_succession_accepted":"political_succession_declined";}else{prefix="political_succession_withdrawal";kind="political_succession_withdrawn";}auto id=common.next_id(prefix);if(!id.ok)return id;auto head=common.append_fact({id.value,kind,political_succession_domain});if(!head.ok)return {false,{},head.error};
  if constexpr(std::is_same_v<T,PoliticalNominateSuccessor>){const auto& p=*x.catalog.policies.find(c.policy_id);PoliticalSuccessionNomination row;row.id=id.value;row.policy_id=p.id;row.organization_id=p.organization_id;row.office_id=p.leader_office_id;row.issuer_actor_id=actor;row.candidate_actor_id=c.candidate_actor_id;row.grant_id=p.nomination_grant_id;row.office_epoch=c.authority.authority_epoch;row.issued_tick=common.tick();row.response_until=common.tick()+p.response_ticks;if(!state.nominations.insert(row.id,row))return {false,{},common_failure("DuplicatePoliticalSuccessionSource").error};}
  else if constexpr(std::is_same_v<T,PoliticalAnswerSuccession>){PoliticalSuccessionAnswer row;row.id=id.value;row.nomination_fact_id=c.nomination_fact_id;row.actor_id=actor;row.tick=common.tick();row.accepted=c.accept;if(const auto* prior=succession_detail::accepted(state,c.nomination_fact_id))row.previous_acceptance_fact_id=prior->id;if(!state.answers.insert(row.id,row))return {false,{},common_failure("DuplicatePoliticalSuccessionSource").error};}
  else{const auto& nomination=*state.nominations.find(c.nomination_fact_id);PoliticalSuccessionWithdrawal row;row.id=id.value;row.nomination_fact_id=nomination.id;row.actor_id=actor;row.grant_id=nomination.grant_id;row.office_epoch=c.authority.authority_epoch;row.tick=common.tick();if(!state.withdrawals.insert(row.id,row))return {false,{},common_failure("DuplicatePoliticalSuccessionSource").error};}return id;
 },command);
}
}
